<script setup>import{inject}from'vue';const s=inject('planAdmin');const limits=[['branch_limit','Branches'],['member_limit','Members'],['doctor_limit','Doctors'],['patient_limit','Patients'],['storage_limit_gb','Storage (GB)'],['appointment_limit','Appointments per month'],['invoice_limit','Invoices per month']];const value=v=>v===null?'Unlimited':Number(v).toLocaleString()</script><template><section class="admin-card"><div class="card-heading"><div><h2>Resource limits</h2><p class="text-sm text-slate-500">Limits used when provisioning new subscriptions.</p></div><RouterLink class="btn-secondary" :to="{name:'admin.plans.edit',params:{id:s.plan.value.id}}">Edit Limits</RouterLink></div><dl class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div v-for="[key,label] in limits" :key="key" class="rounded-xl border p-4"><dt class="text-sm text-slate-500">{{label}}</dt><dd class="mt-1 text-xl font-bold">{{value(s.plan.value[key])}}</dd></div></dl></section></template>
